query:
NODE VALUE out_count SumAgg<INT64> = 0
TABLE results TYPED TABLE {id STRING, degree INT64}

MATCH (p:player)-[e:follow]->(q:player)
PER PATH {
  SET p.@out_count += 1
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id, p.@out_count INTO results
}

FOR r IN results
RETURN r.id AS id, r.degree AS degree
